      "id": "SG-001",
      "name": "Transaction Exception Hierarchy",
      "description": "Defines the complete exception class hierarchy for invalid transactions in the Osaka fork. All exception classes inherit from InvalidTransaction (from ethereum.exceptions). This module establishes the error taxonomy for transaction validation failures.",
      "invariants": [
        {
          "id": "INV-001",
          "text": "All exception classes in this module MUST inherit from InvalidTransaction, ensuring a unified exception handling path for transaction validation."
        },
        {
          "id": "INV-002",
          "text": "Exception classes with Final-annotated fields are immutable after construction; their values are set once in __init__ and cannot be reassigned."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [
        {
          "id": "DS-001",
          "name": "InvalidTransaction",
          "type": "class",
          "description": "Base exception class imported from ethereum.exceptions. Serves as the parent for all transaction-specific exceptions in this module.",
          "source_module": "ethereum.exceptions"
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [],
      "eip_references": []
