    {
      "id": "SG-002",
      "name": "Transaction Type Validation Errors",
      "description": "Handles errors related to EIP-2718 typed transaction envelope validation, including unknown transaction types and disallowed contract creation for certain transaction types.",
      "invariants": [
        {
          "id": "INV-003",
          "text": "TransactionTypeError stores the offending transaction_type as a Final[int], preserving the exact type byte that caused the failure for diagnostic purposes."
        },
        {
          "id": "INV-004",
          "text": "TransactionTypeContractCreationError stores the full Transaction object that attempted an illegal contract creation."
        }
      ],
      "functions": [
        {
          "id": "FN-001",
          "signature": "TransactionTypeError.__init__(self, transaction_type: int)",
          "description": "Constructs a TransactionTypeError with the unknown transaction type byte. Sets error message to 'unknown transaction type `{transaction_type}`' and stores the type value.",
          "parameters": [
            {
              "name": "transaction_type",
              "type": "int",
              "description": "The EIP-2718 transaction type byte that is not recognized."
            }
          ]
        },
        {
          "id": "FN-002",
          "signature": "TransactionTypeContractCreationError.__init__(self, transaction: Transaction)",
          "description": "Constructs a TransactionTypeContractCreationError. Sets error message indicating that the transaction type is not allowed to create contracts, and stores the transaction object.",
          "parameters": [
            {
              "name": "transaction",
              "type": "Transaction",
              "description": "The transaction that attempted disallowed contract creation."
            }
          ]
        }
      ],
      "state_variables": [
