          "fields": [
            {
              "name": "transaction_type",
              "type": "Final[int]"
            }
          ]
        },
        {
          "id": "DS-003",
          "name": "TransactionTypeContractCreationError",
          "type": "class",
          "inherits": "InvalidTransaction",
          "description": "Contract creation is not allowed for a transaction type. Raised when a transaction of a type that prohibits contract creation attempts to create a contract.",
